     9	function getCircularReplacer() {
    10	    const ancestors: unknown[] = [];
    11	    return function (this: unknown, key: string, value: unknown): unknown {
    12	        if (typeof value !== 'object' || value === null) {
    13	            return value;
    14	        }
    15	        // `this` is the object that value is contained in, i.e the direct parent
    16	        // eslint-disable-next-line no-invalid-this
    17	        while (ancestors.length > 0 && ancestors.at(-1) !== this) {
    18	            ancestors.pop();
    19	        }
    20	        if (ancestors.includes(value)) {
    21	            return '[Circular]';
    22	        }
    23	        ancestors.push(value);
    24	        return value;
    25	    };
    26	}
    27	
    28	function serializeLoggingData<T extends Record<string, unknown> | undefined>(logData: T): T | null {
    29	    try {
    30	        return JSON.parse(JSON.stringify(logData, getCircularReplacer())) as T;
    31	    } catch (error) {
    32	        Log.hmmm('Failed to serialize log data', {error});
    33	        return null;
    34	    }
    35	}
    36	
    37	function logRequestDetails(message: string, request: Request, response?: Response | void) {
    38	    // Don't log about log or else we'd cause an infinite loop
    39	    if (request.command === 'Log') {
    40	        return;
    41	    }
    42	
    43	    const logParams: Record<string, unknown> = {
    44	        command: request.command,
    45	        shouldUseSecure: request.shouldUseSecure,
    46	    };
    47	
    48	    const returnValueList = request?.data?.returnValueList;
    49	    if (returnValueList) {
    50	        logParams.returnValueList = returnValueList;
    51	    }
    52	
    53	    const nvpNames = request?.data?.nvpNames;
    54	    if (nvpNames) {
    55	        logParams.nvpNames = nvpNames;
    56	    }
    57	
    58	    if (response) {
    59	        logParams.jsonCode = response.jsonCode;
    60	        logParams.requestID = response.requestID;
    61	    }
    62	
    63	    const extraData: Record<string, unknown> = {};
    64	    /**
    65	     * We don't want to log the request and response data for AuthenticatePusher
    66	     * requests because they contain sensitive information.
    67	     */
    68	    if (request.command !== 'AuthenticatePusher') {
    69	        extraData.request = {
    70	            ...request,
    71	            data: serializeLoggingData(request.data),
    72	        };
    73	        extraData.response = response;
    74	    }
    75	
    76	    Log.info(message, false, logParams, false, extraData);
    77	}
    78	
    79	const Logging: Middleware = (response, request) => {
    80	    const startTime = Date.now();
    81	    logRequestDetails('[Network] Making API request', request);
    82	    return response
    83	        .then((data) => {
    84	            logRequestDetails(`[Network] Finished API request in ${Date.now() - startTime}ms`, request, data);
    85	            return data;
    86	        })
    87	        .catch((error: HttpsError) => {
    88	            const logParams: Record<string, unknown> = {
    89	                message: error.message,
    90	                status: error.status,
    91	                title: error.title,
    92	                request,
    93	            };
    94	
    95	            if (error.name === CONST.ERROR.REQUEST_CANCELLED) {
    96	                // Cancelled requests are normal and can happen when a user logs out.
    97	                Log.info('[Network] API request error: Request canceled', false, logParams);
    98	            } else if (error.message === CONST.ERROR.FAILED_TO_FETCH) {
    99	                // If the command that failed is Log it's possible that the next call to Log may also fail.
   100	                // This will lead to infinitely complex log params that can eventually crash the app.
   101	                if (request.command === 'Log') {
   102	                    delete logParams.request;
   103	                }
   104	
   105	                // Log when we get a "Failed to fetch" error. Very common if a user is offline or experiencing an unlikely scenario like
   106	                // incorrect url, bad cors headers returned by the server, DNS lookup failure etc.
   107	                Log.hmmm('[Network] API request error: Failed to fetch', logParams);
   108	            } else if (
   109	                [
   110	                    CONST.ERROR.IOS_NETWORK_CONNECTION_LOST,
   111	                    CONST.ERROR.NETWORK_REQUEST_FAILED,
   112	                    CONST.ERROR.IOS_NETWORK_CONNECTION_LOST_RUSSIAN,
   113	                    CONST.ERROR.IOS_NETWORK_CONNECTION_LOST_SWEDISH,
   114	                    CONST.ERROR.IOS_NETWORK_CONNECTION_LOST_SPANISH,
   115	                ].some((message) => message === error.message)
   116	            ) {
   117	                // These errors seem to happen for native devices with interrupted connections. Often we will see logs about Pusher disconnecting together with these.
   118	                // This type of error may also indicate a problem with SSL certs.
   119	                Log.hmmm('[Network] API request error: Connection interruption likely', logParams);
   120	            } else if ([CONST.ERROR.FIREFOX_DOCUMENT_LOAD_ABORTED, CONST.ERROR.SAFARI_DOCUMENT_LOAD_ABORTED].some((message) => message === error.message)) {
   121	                // This message can be observed page load is interrupted (closed or navigated away).
   122	                Log.hmmm('[Network] API request error: User likely navigated away from or closed browser', logParams);
   123	            } else if (error.message === CONST.ERROR.IOS_LOAD_FAILED) {
   124	                // Not yet clear why this message occurs, but it is specific to iOS and tends to happen around the same time as a Pusher code 1006
   125	                // which is when a websocket disconnects. So it seems likely to be a spotty connection scenario.
   126	                Log.hmmm('[Network] API request error: iOS Load Failed error', logParams);
   127	            } else if (error.message === CONST.ERROR.SAFARI_CANNOT_PARSE_RESPONSE) {
   128	                // Another cryptic Apple error message. Unclear why this can happen, but some speculation it can be fixed by a browser restart.
   129	                Log.hmmm('[Network] API request error: Safari "cannot parse response"', logParams);
   130	            } else if (error.message === CONST.ERROR.GATEWAY_TIMEOUT) {
   131	                // This error seems to only throw on dev when localhost:8080 tries to access the production web server. It's unclear whether this can happen on production or if
   132	                // it's a sign that the web server is down.
   133	                Log.hmmm('[Network] API request error: Gateway Timeout error', logParams);
   134	            } else if (request.command === SIDE_EFFECT_REQUEST_COMMANDS.AUTHENTICATE_PUSHER) {
   135	                // AuthenticatePusher requests can return with fetch errors and no message. It happens because we return a non 200 header like 403 Forbidden.
   136	                // This is common to see if we are subscribing to a bad channel related to something the user shouldn't be able to access. There's no additional information
   137	                // we can get about these requests.
   138	                Log.hmmm('[Network] API request error: AuthenticatePusher', logParams);
   139	            } else if (error.message === CONST.ERROR.EXPENSIFY_SERVICE_INTERRUPTED) {
   140	                // Expensify site is down completely OR
   141	                // Auth (database connection) is down / bedrock has timed out while making a request. We currently can't tell the difference between Auth down and bedrock timing out.
   142	                Log.hmmm('[Network] API request error: Expensify service interrupted or timed out', logParams);
   143	            } else if (error.message === CONST.ERROR.THROTTLED) {
   144	                Log.hmmm('[Network] API request error: Expensify API throttled the request', logParams);
   145	            } else if (error.message === CONST.ERROR.DUPLICATE_RECORD) {
   146	                // Duplicate records can happen when a large upload is interrupted and we need to retry to see if the original request completed
   147	                Log.info('[Network] API request error: A record already exists with this ID', false, logParams);
   148	            } else {
   149	                // If we get any error that is not known log an alert so we can learn more about it and document it here.
   150	                Log.alert(`${CONST.ERROR.ENSURE_BUGBOT} unknown API request error caught while processing request`, logParams, false);
   151	            }
   152	
   153	            // Re-throw this error so the next handler can manage it
   154	            throw error;
   155	        });
   156	};
   157	
   158	export default Logging;
   159	
   160	export {serializeLoggingData};
